    }

    class VisitController {
        <<class>>
        -OwnerRepository owners
        +VisitController(owners OwnerRepository)
    }

    class PetController {
        <<class>>
        -OwnerRepository owners
        -PetTypeRepository types
        +PetController(owners OwnerRepository, types PetTypeRepository)
    }

